import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import * as S from './state.js';
import * as W from './world.js';
import * as P from './parts.js';
import * as U from './ui.js';
import * as Q from './sequence.js';
import * as F from './storage.js';

const app=document.querySelector('#app');
if(app&&S.initialState){
for(const id of ['home','workshop','file-panel','part-panel','timeline-panel']){const el=document.getElementById(id);if(el&&!el.contains(app))el.hidden=true}
const injected=document.createElement('style');injected.textContent="#view{height:60vh;min-height:440px;background:#0c1727}#view canvas{display:block}.kit-toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:14px}.kit-layout{display:grid;grid-template-columns:230px 1fr;gap:12px}#parts{display:flex;flex-direction:column;gap:8px}#props input:not([type=checkbox]),.kit-step input{width:100%;min-width:0;padding:6px;background:#17283c;color:#e8f2ff;border:1px solid #42566e}#props fieldset,.kit-step fieldset{display:flex;gap:8px;border:1px solid #354963}#props label,.kit-step label{display:block;min-width:0;font-size:14px}#props fieldset label,.kit-step fieldset label{flex:1}.kit-step{border:1px solid #354963;padding:14px;margin:12px 0}.kit-toolbar label{border:1px solid #40516a;padding:8px;border-radius:5px;font-size:14px}.kit-toolbar input[type=file]{max-width:210px}.kit-step button{margin:4px}#notice{padding:0 18px;font-size:14px;color:#b5f46b}@media(max-width:700px){.kit-layout{grid-template-columns:1fr}.kit-layout aside{display:grid;grid-template-columns:1fr 1fr;gap:12px}#view{height:55vh;min-height:320px}}";document.head.appendChild(injected);
let state=S.initialState(),world,playing=false,playTime=0,last=0,activeStep=0;
state.steps ||= [];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
app.innerHTML=`<div class="kit-toolbar"><button id="sample">サンプルCubeSat</button><label>複数STLを追加 <input id="stls" type="file" accept=".stl" multiple></label><button id="save">プロジェクトを保存</button><label>JSONを開く <input id="project" type="file" accept=".json"></label><button id="localSave">ブラウザに保存</button><button id="localLoad">ブラウザから復元</button></div><p id="notice" role="status">習得した機能がここに増えていきます。</p><div class="kit-layout"><aside><h2>部品</h2><div id="parts"></div><div id="props"></div></aside><div id="view"></div></div><section><h2>組立タイムライン</h2><p>部品を選んで追加。上・下ボタンまたはドラッグで順番を変え、開始位置・到着位置・秒数を編集します。</p><button id="addStep">選択部品の手順を追加</button><button id="play">再生 / 一時停止</button><button id="stop">最初へ</button><label>再生位置 <input id="scrub" type="range" min="0" max="1" step="0.001" value="0"></label><div id="steps"></div></section>`;
const $=id=>document.getElementById(id),notice=t=>$('notice').textContent=t;
function requireFeature(fn,name){if(!fn){notice(name+'は後のドリルで作ります。');return false}return true}
function selected(){return state.parts.find(p=>p.id===state.selectedId)}
function renderParts(){if(U.renderPartList)U.renderPartList($('parts'),state.parts,id=>{state.selectedId=id;renderProps();renderParts()});else $('parts').textContent=state.parts.map(p=>p.name).join(' / ');renderProps()}
function renderProps(){const p=selected();if(!p){$('props').textContent='部品を選択してください';return}$('props').innerHTML=`<h3>選択部品</h3><label>部品名<input id="partName" value="${esc(p.name)}"></label><label>色<input id="partColor" type="color" value="${p.color}"></label><label>不透明度<input id="partOpacity" type="range" min="0" max="1" step=".05" value="${p.opacity}"></label><label><input id="partVisible" type="checkbox" ${p.visible?'checked':''}>表示する</label><fieldset><legend>位置（STL座標の単位）</legend>${['x','y','z'].map((a,i)=>`<label>${a}<input id="pos${i}" type="number" step="1" value="${p.position[i]}"></label>`).join('')}</fieldset><fieldset><legend>回転（度）</legend>${['x','y','z'].map((a,i)=>`<label>${a}<input id="rot${i}" type="number" step="5" value="${p.rotation[i]}"></label>`).join('')}</fieldset><button id="removePart">部品を外す</button>`;
$('partName').onchange=e=>{p.name=e.target.value;renderParts()};$('partColor').oninput=e=>{p.color=e.target.value;U.setColor?.(p.mesh,p.color)};$('partOpacity').oninput=e=>{p.opacity=+e.target.value;U.setOpacity?.(p.mesh,p.opacity)};$('partVisible').onchange=e=>{p.visible=e.target.checked;U.setVisible?.(p.mesh,p.visible)};
for(let i=0;i<3;i++){ $('pos'+i).onchange=e=>{const v=+e.target.value;if(!Number.isFinite(v))return;p.position[i]=v;P.setPosition?.(p.mesh,...p.position)};$('rot'+i).onchange=e=>{const v=+e.target.value;if(!Number.isFinite(v))return;p.rotation[i]=v;P.setRotation?.(p.mesh,...p.rotation)}}
$('removePart').onclick=()=>{world?.scene.remove(p.mesh);p.mesh.geometry.dispose();p.mesh.material.dispose();state.parts=state.parts.filter(x=>x!==p);state.steps=state.steps.filter(s=>s.partId!==p.id);state.selectedId=null;renderParts();renderSteps()};}
async function addGeometries(items){if(state.parts.length+items.length>30)throw Error('合計30部品までです');if(!world||!W.createMesh||!S.makePartRecord){notice('3D・部品データのドリルを先に完成させてください。');return}for(const item of items){const id=S.nextId?S.nextId(state.parts):'part-'+(state.parts.length+1);const p=S.makePartRecord(id,item.name);p.source=item.source||null;if(item.position)p.position=[...item.position];p.mesh=W.createMesh(item.geometry,W.createMaterial?.(p.color));P.setPosition?.(p.mesh,...p.position);p.mesh.userData.partId=id;world.scene.add(p.mesh);state.parts.push(p)}if(!state.selectedId)state.selectedId=state.parts[0]?.id;frameAll();renderParts();notice(`${state.parts.length}部品を登録しました。STLの単位は自動推定しません。CAD側で揃えてください。`)}
function frameAll(){if(!world||!state.parts.length)return;const b=new THREE.Box3();state.parts.forEach(p=>b.expandByObject(p.mesh));const center=b.getCenter(new THREE.Vector3());const size=Math.max(...b.getSize(new THREE.Vector3()).toArray(),1);world.controls.target.copy(center);world.camera.position.copy(center).add(new THREE.Vector3(size*1.8,size*1.3,size*1.8));world.camera.near=Math.max(size/10000,.001);world.camera.far=size*100;world.camera.updateProjectionMatrix();world.controls.update()}
if(W.createScene&&W.createCamera&&W.createRenderer){const view=$('view'),scene=W.createScene(),camera=W.createCamera(1),renderer=W.createRenderer(view);W.addLights?.(scene);const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;world={scene,camera,renderer,controls};const resize=()=>{if(W.resizeView)W.resizeView(renderer,camera,view.clientWidth,view.clientHeight);else{renderer.setSize(view.clientWidth,view.clientHeight);camera.aspect=view.clientWidth/Math.max(view.clientHeight,1);camera.updateProjectionMatrix()}};new ResizeObserver(resize).observe(view);resize();renderer.domElement.addEventListener('click',e=>{if(U.pickPart){const p=U.pickPart(e,renderer.domElement,camera,state.parts);if(p){state.selectedId=p.id||p;renderParts()}}});renderer.setAnimationLoop(t=>{const dt=last?Math.min((t-last)/1000,.1):0;last=t;if(playing&&state.steps.length){const total=state.steps.reduce((n,s)=>n+s.duration,0);playTime=Math.min(playTime+dt,total);let rem=playTime,progress=0;for(let i=0;i<state.steps.length;i++){const d=state.steps[i].duration;if(rem<=d){progress=i+rem/d;break}rem-=d;progress=i+1}applyProgress(progress);$('scrub').value=playTime/total;if(playTime>=total)playing=false}controls.update();renderer.render(scene,camera)})}
function applyProgress(progress){if(!Q.projectAt)return;const poses=Q.projectAt(state.parts,state.steps,progress);poses.forEach(p=>{const original=state.parts.find(x=>x.id===p.id);if(original)original.mesh.position.set(...p.position)})}
function renderSteps(){const box=$('steps');box.innerHTML='';state.steps.forEach((s,i)=>{const row=document.createElement('div');row.className='kit-step';row.draggable=true;row.innerHTML=`<strong>${i+1}. ${esc(state.parts.find(p=>p.id===s.partId)?.name||s.partId)}</strong><button data-up>上へ</button><button data-down>下へ</button><button data-delete>削除</button><label>秒数<input type="number" min=".1" step=".1" value="${s.duration}" data-duration></label>${['from','to'].map(key=>`<fieldset><legend>${key==='from'?'開始位置':'到着位置'}</legend>${s[key].map((v,j)=>`<label>${['x','y','z'][j]}<input type="number" value="${v}" data-key="${key}" data-j="${j}"></label>`).join('')}</fieldset>`).join('')}`;
const move=to=>{if(to<0||to>=state.steps.length)return;if(Q.moveStep)state.steps=Q.moveStep(state.steps,i,to);playing=false;renderSteps()};row.querySelector('[data-up]').onclick=()=>move(i-1);row.querySelector('[data-down]').onclick=()=>move(i+1);row.querySelector('[data-delete]').onclick=()=>{state.steps.splice(i,1);renderSteps()};row.querySelector('[data-duration]').onchange=e=>{const v=+e.target.value;if(Number.isFinite(v)&&v>0)s.duration=v;else e.target.value=s.duration};row.querySelectorAll('[data-key]').forEach(input=>input.onchange=()=>{const v=+input.value;if(Number.isFinite(v))s[input.dataset.key][+input.dataset.j]=v});row.ondragstart=()=>{activeStep=i};row.ondragover=e=>e.preventDefault();row.ondrop=e=>{e.preventDefault();if(Q.moveStep)state.steps=Q.moveStep(state.steps,activeStep,i);renderSteps()};box.appendChild(row)})}
$('sample').onclick=async()=>{if(requireFeature(P.makeSampleParts,'サンプル生成'))await addGeometries(P.makeSampleParts())};$('stls').onchange=async e=>{if(!requireFeature(P.loadFiles,'STLの読み込み'))return;try{await addGeometries(await P.loadFiles(e.target.files))}catch(err){notice('読み込み失敗：'+err.message)}e.target.value=''};
$('addStep').onclick=()=>{const p=selected();if(!p){notice('部品を選んでください');return}if(!requireFeature(Q.createStep,'組立手順'))return;const step=Q.createStep(p.id);step.to=[...p.position];step.from=p.position.map((v,i)=>v+(i===1?150:0));state.steps.push(step);renderSteps()};$('play').onclick=()=>{if(!state.steps.length){notice('手順を追加してください');return}if(Q.validateSteps&&!Q.validateSteps(state.steps,state.parts.map(p=>p.id))){notice('組立手順の値を確認してください');return}playing=!playing;if(playTime>=state.steps.reduce((n,s)=>n+s.duration,0))playTime=0};$('stop').onclick=()=>{playing=false;playTime=0;$('scrub').value=0;applyProgress(0)};$('scrub').oninput=e=>{playing=false;const frac=+e.target.value;playTime=frac*state.steps.reduce((n,s)=>n+s.duration,0);let rem=playTime,progress=0;for(let i=0;i<state.steps.length;i++){const d=state.steps[i].duration;if(rem<=d){progress=i+rem/d;break}rem-=d;progress=i+1}applyProgress(progress)};
function bufferBase64(buffer){if(!buffer)return null;const bytes=new Uint8Array(buffer);let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(binary)}
function geometrySTL(mesh){const raw=mesh.geometry.index?mesh.geometry.toNonIndexed():mesh.geometry;const pos=raw.getAttribute('position');let text='solid part\n';for(let i=0;i<pos.count;i+=3){const a=new THREE.Vector3().fromBufferAttribute(pos,i),b=new THREE.Vector3().fromBufferAttribute(pos,i+1),c=new THREE.Vector3().fromBufferAttribute(pos,i+2);const n=b.clone().sub(a).cross(c.clone().sub(a)).normalize();text+='facet normal '+n.toArray().join(' ')+'\nouter loop\n';for(const v of [a,b,c])text+='vertex '+v.toArray().join(' ')+'\n';text+='endloop\nendfacet\n'}text+='endsolid part\n';if(raw!==mesh.geometry)raw.dispose();return new TextEncoder().encode(text).buffer}
function packageProject(){return {version:1,parts:state.parts.map(({mesh,source,...p})=>({...p,source:bufferBase64(source||geometrySTL(mesh))})),steps:state.steps}}
async function restore(data){if(!F.validateProject?.(data))throw Error('プロジェクト形式が不正です');if(!P.parseSTL)throw Error('STL読み込み機能を先に作ってください');const prepared=data.parts.map(p=>{if(!p.source)throw Error('STLデータがありません');const buffer=Uint8Array.from(atob(p.source),c=>c.charCodeAt(0)).buffer;return {...p,buffer,geometry:P.parseSTL(buffer)}});for(const p of state.parts){world?.scene.remove(p.mesh);p.mesh.geometry.dispose();p.mesh.material.dispose()}state.parts=[];for(const p of prepared){await addGeometries([{name:p.name,source:p.buffer,geometry:p.geometry,position:p.position}]);const added=state.parts.at(-1);const {buffer,geometry,...metadata}=p;Object.assign(added,metadata);added.source=buffer;added.mesh.userData.partId=p.id;P.setPosition?.(added.mesh,...p.position);P.setRotation?.(added.mesh,...p.rotation);U.setColor?.(added.mesh,p.color);U.setOpacity?.(added.mesh,p.opacity);U.setVisible?.(added.mesh,p.visible)}state.steps=data.steps;state.selectedId=state.parts[0]?.id;renderParts();renderSteps();frameAll();notice('STLと編集設定を復元しました')}
$('save').onclick=()=>{if(!requireFeature(F.serializeProject,'JSON保存')||!requireFeature(F.downloadText,'ファイル保存'))return;F.downloadText('assembly-project.json',F.serializeProject(packageProject()))};$('project').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>50*1024*1024)throw Error('50MB以下のJSONを選んでください');await restore(F.parseProject(await f.text()))}catch(err){notice(err.message)}e.target.value=''};$('localSave').onclick=()=>{try{if(!requireFeature(F.saveLocal,'ブラウザ保存'))return;F.saveLocal('my-assembly',packageProject());notice('このブラウザに保存しました')}catch(e){notice('保存できません：'+e.message)}};$('localLoad').onclick=async()=>{try{if(!requireFeature(F.restoreLocal,'復元'))return;const data=F.restoreLocal('my-assembly');if(!data)throw Error('保存が見つかりません');await restore(data)}catch(e){notice(e.message)}};
renderParts();renderSteps();
if(P.makeSampleParts&&world&&W.createMesh)await addGeometries(P.makeSampleParts());
globalThis.__assembly={get state(){return state},world};
}else if(app){app.textContent='ここから自分のアプリを育てます。HTML・CSS・JavaScriptを順番に追加すると、操作できる画面ができます。'}
